fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    // Check if string is empty
    if txt.is_empty() {
        return false;
    }
    
    // Get the last character
    let last_char = match txt.chars().last() {
        Some(c) => c,
        None => return false, // This shouldn't happen since we checked is_empty, but for safety
    };
    
    // Check if last character is ASCII alphabetic
    if !last_char.is_ascii_alphabetic() {
        return false;
    }
    
    // Check string length in characters
    let char_count = txt.chars().count();
    
    if char_count == 1 {
        return true;
    }
    
    // Get the second-to-last character
    let second_last_char = txt.chars().rev().nth(1);
    
    // Check if second-to-last character is a space
    match second_last_char {
        Some(' ') => true,
        _ => false,
    }
}